/* updateSrngGrdngPopScrenn (면접심사채점표 스크리닝문항 (저장)) - Lee Hye Sun */
UPDATE AFA100 SET
      TRPR_INFO_NO = #{TRPR_INFO_NO}
    , APLY_RCPT_SN = #{APLY_RCPT_SN}
    , INTRVW_PTCPTN_SE_CD = #{INTRVW_PTCPTN_SE_CD}
    , GHVR_OBSERV_INTRVW_PRTCLR_MATTER_CN = #{GHVR_OBSERV_INTRVW_PRTCLR_MATTER_CN}
    , APLY_RCPT_SRNG_PRGRS_STTS_SE_CD = #{APLY_RCPT_SRNG_PRGRS_STTS_SE_CD}
    , RQST_CS_CN = #{RQST_CS_CN}
    , MTCLTN_LVING_RELATA_CN = #{MTCLTN_LVING_RELATA_CN}
    , COGNZC_DEVLPA_SITTN_CN = #{COGNZC_DEVLPA_SITTN_CN}
    , BDY_MIND_HEALTH_RELATA_CN = #{BDY_MIND_HEALTH_RELATA_CN}
    , FAM_SITTN_CN = #{FAM_SITTN_CN}
    , INTERV_GENRVW_CN = #{INTERV_GENRVW_CN}
    , DEPTHS_ARGMT_MATTER_CN = #{DEPTHS_ARGMT_MATTER_CN}
    , YNGBGS_SCORE = #{YNGBGS_SCORE}
    , PRTCR_SCORE = #{PRTCR_SCORE}
    , INTRVW_SRNG_GENRVW_CN = #{INTRVW_SRNG_GENRVW_CN}
    , INTRVW_SRNG_PIC_NM_ENCPT = ENC_B64(#{INTRVW_SRNG_PIC_NM_ENCPT})
    , LAST_MDFR_ID = #{LAST_MDFR_ID}
    , LAST_MDFCN_DT = SYSDATE
WHERE TRPR_INFO_NO = #{TRPR_INFO_NO}
AND APLY_RCPT_SN = #{APLY_RCPT_SN}

